  carEnter: 6.9,     // ورود ماشین از لبه‌ی چپ
  catchDX: 14,       // جای بازیکن روی ماشین (نسبت به مرکز ماشین)
  driveStart: 9.15,  // شروع بخش رانندگی (بازیکن سوار شد)
